<script setup lang="ts">
import { definePageMeta, useAsyncData, useLocalePath, useProductModule } from "#imports";
import { PERMISSION } from "~/constants/permissions";
definePageMeta({ middleware: ["auth-guard"], permissions: [PERMISSION.PRODUCTS_READ] });
const lp = useLocalePath();
const { fetchProducts } = useProductModule();
const { data: preparations } = await useAsyncData("internal-preparations", () => fetchProducts({ filters: { is_internal_preparation: true } }));
</script>
<template><div class="space-y-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-2xl font-semibold">{{ $t("internal_preparations.title") }}</h1><p class="text-sm text-muted">{{ $t("internal_preparations.description") }}</p></div><UButton icon="i-lucide-plus" color="primary" :to="lp('/internal-preparations/create')">{{ $t("internal_preparations.new") }}</UButton></div><UCard><table class="w-full text-left"><thead class="border-b border-default text-sm text-muted"><tr><th class="p-3">{{ $t("products.name") }}</th><th class="p-3">{{ $t("products.category") }}</th><th class="p-3">{{ $t("products.shelf_life_days") }}</th><th class="p-3">{{ $t("common.action") }}</th></tr></thead><tbody><tr v-for="preparation in preparations?.data ?? []" :key="preparation.id" class="border-b border-default last:border-0"><td class="p-3 font-medium">{{ preparation.name }}</td><td class="p-3">{{ preparation.category?.name ?? '—' }}</td><td class="p-3">{{ preparation.shelf_life_days ?? '—' }}</td><td class="p-3"><div class="flex gap-1"><UButton icon="i-lucide-chef-hat" color="primary" variant="soft" :to="lp('/products/produce-' + preparation.id)">{{ $t("products.produce") }}</UButton><UButton icon="i-lucide-pencil" variant="ghost" :to="lp('/internal-preparations/edit-' + preparation.id)" /></div></td></tr><tr v-if="!(preparations?.data?.length)"><td colspan="4" class="p-6 text-center text-muted">{{ $t("internal_preparations.empty") }}</td></tr></tbody></table></UCard></div></template>
